/**
 * Opt-in integration test: runs the REAL OpenThai model in the Python
 * worker on a synthetic image (invented content, generated by
 * tools/make-synthetic-receipt.ts — not a real receipt).
 *
 *   bun run ocr:setup     # once
 *   bun run test:ocr
 *
 * Skipped unless OPENTHAI_INTEGRATION=1, so `bun test` and CI stay offline
 * and need neither Python nor the weights.
 */
import { afterAll, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
	editDistance,
	graphemes,
	type OcrImage,
	type OcrResult,
	ocrText,
} from "@receipt-extractor/core";
import { createLocalOpenThaiOcr } from "./create.ts";
import { REPO_ROOT, readModelPin } from "./paths.ts";
import { OpenThaiLocalProvider } from "./provider.ts";

const enabled = process.env.OPENTHAI_INTEGRATION === "1";
const IMAGES = join(REPO_ROOT, "evals", "dataset", "synthetic", "images");

async function fixture(): Promise<{
	image: OcrImage;
	expected: { rows: string[]; width: number; height: number };
}> {
	return {
		image: {
			bytes: new Uint8Array(
				await readFile(join(IMAGES, "synthetic-receipt.png")),
			),
			mime_type: "image/png",
		},
		expected: JSON.parse(
			await readFile(join(IMAGES, "synthetic-receipt.expected.json"), "utf8"),
		),
	};
}

function report(title: string, result: OcrResult): void {
	console.log(`\n${title}: ${result.model}, ${result.duration_ms} ms`);
	for (const line of result.lines) {
		console.log(
			`  row ${String(line.row).padStart(2)}  conf ${line.confidence?.toFixed(4)}  ${line.text}`,
		);
	}
	for (const line of result.dropped ?? []) {
		console.log(
			`  DROPPED (${line.reason}) conf ${line.confidence}  ${line.text}`,
		);
	}
}

describe.skipIf(!enabled)(
	"OpenThai local OCR — real model, synthetic image",
	() => {
		const provider = new OpenThaiLocalProvider({
			expectedRevision: readModelPin().revision,
		});
		const cleanup: string[] = [];
		afterAll(async () => {
			await provider.close();
			await Promise.all(
				cleanup.map((dir) => rm(dir, { recursive: true, force: true })),
			);
		});

		test("reads printed Thai and English text and prices", async () => {
			const { image, expected } = await fixture();
			const ready = await provider.start();
			console.log(
				`\nmodel loaded in ${ready.load_ms} ms: ${ready.model}@${ready.revision} (${ready.backend})`,
			);

			const result = await provider.recognize(image);
			report("first read", result);

			// The pinned revision is what actually ran.
			expect(ready.revision).toBe(readModelPin().revision);
			expect(result.model).toContain(readModelPin().revision);

			// Every line has the official shape: text, 0..1 confidence, row, 4 corners inside the image.
			expect(result.lines.length).toBeGreaterThanOrEqual(expected.rows.length);
			for (const line of result.lines) {
				expect(line.text.length).toBeGreaterThan(0);
				expect(line.confidence).toBeGreaterThan(0);
				expect(line.confidence).toBeLessThanOrEqual(1);
				expect(line.row).toBeGreaterThanOrEqual(0);
				expect(line.box).toHaveLength(4);
				for (const point of line.box ?? []) {
					expect(point.x).toBeGreaterThanOrEqual(-2);
					expect(point.x).toBeLessThanOrEqual(expected.width + 2);
					expect(point.y).toBeGreaterThanOrEqual(-2);
					expect(point.y).toBeLessThanOrEqual(expected.height + 2);
				}
			}

			// Reading order: one text row per printed row, top to bottom.
			const rows = ocrText(result).split("\n");
			expect(rows).toHaveLength(expected.rows.length);

			// Text accuracy over the whole image, in grapheme clusters.
			const reference = graphemes(expected.rows.join("\n").normalize("NFC"));
			const hypothesis = graphemes(rows.join("\n").normalize("NFC"));
			const cer = editDistance(reference, hypothesis) / reference.length;
			const wrongRows = expected.rows.filter((row, i) => row !== rows[i]);
			console.log(
				`\nCER ${(cer * 100).toFixed(2)}% (${reference.length} grapheme clusters), ${expected.rows.length - wrongRows.length}/${expected.rows.length} rows exact`,
			);
			for (const [i, row] of expected.rows.entries()) {
				if (row !== rows[i])
					console.log(`  expected "${row}"\n  got      "${rows[i]}"`);
			}
			// Clean, printed, synthetic text: generous bound, so the test checks
			// that the pipeline works rather than pinning exact model behaviour.
			expect(cer).toBeLessThan(0.05);

			// Every printed price is read exactly, as its own line.
			const texts = result.lines.map((line) => line.text);
			for (const price of [
				"14.00",
				"20.00",
				"35.00",
				"-5.00",
				"64.00",
				"4.19",
				"100.00",
				"36.00",
			]) {
				expect(texts).toContain(price);
			}
			// Thai and English both come through.
			expect(rows.join("\n")).toContain("ขนมข้าวพองสมมติ 48ก");
			expect(rows.join("\n")).toContain("ชาเย็นหอม DEMO TEA");
		}, 120_000);

		test("the same worker reads again without reloading the model", async () => {
			const { image } = await fixture();
			const pid = provider.pid;
			const again = await provider.recognize(image);
			console.log(`\nsecond read, same process: ${again.duration_ms} ms`);
			expect(provider.pid).toBe(pid);
			expect(again.lines.length).toBeGreaterThan(0);
		}, 60_000);

		test("the disk cache serves a repeat read without starting Python", async () => {
			const { image } = await fixture();
			const cacheDir = await mkdtemp(join(tmpdir(), "ocr-cache-int-"));
			cleanup.push(cacheDir);

			const first = createLocalOpenThaiOcr({ cacheDir });
			const read = await first.provider.recognize(image);
			await first.close();
			expect(read.cache_hit).toBe(false);

			const second = createLocalOpenThaiOcr({ cacheDir });
			const started = performance.now();
			const hit = await second.provider.recognize(image);
			const elapsed = performance.now() - started;
			expect(second.local.pid).toBeUndefined();
			await second.close();

			console.log(
				`\ncache: first read ${read.duration_ms} ms (plus process start), repeat ${elapsed.toFixed(1)} ms from disk`,
			);
			expect(hit.cache_hit).toBe(true);
			expect(hit.lines).toEqual(read.lines);
			expect(hit.model).toBe(read.model);
		}, 120_000);
	},
);
